_DECODED = {
    path: (mime, etag, zlib.decompress(base64.b85decode(payload)))
    for path, (mime, etag, payload) in _ASSETS.items()
}

@app.after_request
def security_headers(response):
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["X-Frame-Options"] = "DENY"
    response.headers["Referrer-Policy"] = "no-referrer"
    response.headers["Permissions-Policy"] = "camera=(), microphone=(), geolocation=()"
    response.headers["Content-Security-Policy"] = (
        "default-src 'self'; script-src 'self'; style-src 'self' 'unsafe-inline'; "
        "img-src 'self' data: blob:; connect-src 'self' https://dns.google https://ipwho.is; "
        "object-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'self'"
    )
    return response

@app.get("/healthz")
def health():
    return {"status": "ok", "app": "quantum-omega"}

def asset_response(path):
    mime, etag, content = _DECODED[path]
    response = Response(content, content_type=mime)
    response.set_etag(etag)
    response.headers["Cache-Control"] = "no-cache"
    return response.make_conditional(request)

@app.get("/")
@app.get("/index")
def index():
    return asset_response("/")

@app.get("/assets/<name>")
def asset(name):
    path = "/assets/" + name
    if path not in _DECODED:
        return Response("Not found", status=404, content_type="text/plain")
    return asset_response(path)

@app.get("/favicon.ico")
def favicon():
    return asset_response("/favicon.ico")

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=int(os.environ.get("PORT", "8000")), debug=False)
